// Keywords with an empty status, up to max_keywords. row_number comes from the Google Sheets node and marks the row as done later.
const cfg = $('Config').first().json;
// The DataForSEO nodes take location and language names; codes from the sheet are translated, names pass through.
const LOCATIONS = { 2840: 'United States', 2826: 'United Kingdom', 2616: 'Poland', 2276: 'Germany', 2040: 'Austria', 2756: 'Switzerland', 2250: 'France', 2380: 'Italy', 2724: 'Spain', 2528: 'Netherlands', 2203: 'Czechia', 2703: 'Slovakia', 2752: 'Sweden', 2124: 'Canada', 2036: 'Australia', 2356: 'India' };
const LANGUAGES = { en: 'English', es: 'Spanish', pl: 'Polish', de: 'German', fr: 'French', it: 'Italian', nl: 'Dutch', cs: 'Czech', sk: 'Slovak', sv: 'Swedish', hi: 'Hindi' };
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const keyword = String(r.keyword ?? '').trim();
  if (!keyword || String(r.status ?? '').trim()) continue;
  const country_code = Number(r.country_code) || 2840, language_code = String(r.language_code || 'en').trim();
  out.push({ json: { row_number: r.row_number, keyword, country_code, language_code,
    location_name: LOCATIONS[country_code] || String(r.country_code || 'United States').trim(), language_name: LANGUAGES[language_code] || language_code } });
  if (out.length >= Number(cfg.max_keywords || 10)) break;
}
return out;

// Organic top 10 plus People Also Ask, related searches and AI Overview as context. Costs are summed as reported by DataForSEO.
const kw = $('Loop over keywords').first().json;
const r = $input.first().json;
const task = (r.tasks || [])[0] || {};
const state = {
  row_number: kw.row_number, keyword: kw.keyword, country_code: kw.country_code, language_code: kw.language_code, location_name: kw.location_name, language_name: kw.language_name,
  results: [], features: { people_also_ask: [], related_searches: [], ai_overview: '', item_types: [] },
  cost: { serp: Number(task.cost || 0), pages: 0, volume: 0, traffic: 0, model: 0 }, tokens: { in: 0, out: 0 }, demand: null, error: ''
};
if (task.status_code !== 20000) {
  state.error = 'DataForSEO SERP: ' + (task.status_message || r.status_message || 'request failed');
  return [{ json: state }];
}
const res = (task.result || [])[0] || {};
state.features.item_types = res.item_types || [];
for (const it of res.items || []) {
  if (it.type === 'organic' && state.results.length < 10) {
    state.results.push({
      result_id: 'r' + String(state.results.length + 1).padStart(2, '0'), rank: it.rank_group, url: it.url || '',
      domain: String(it.domain || '').replace(/^www\./, ''), title: it.title || '', description: String(it.description || '').slice(0, 220),
      highlighted: (it.highlighted || []).slice(0, 4), digest: '', fetch_status: 'not_read', words: null, chars: null, elements: null, etv: null
    });
  } else if (it.type === 'people_also_ask') {
    for (const q of it.items || []) if (q.title) state.features.people_also_ask.push(q.title);
  } else if (it.type === 'related_searches') {
    for (const q of it.items || []) if (q) state.features.related_searches.push(q);
  } else if (it.type === 'ai_overview') {
    state.features.ai_overview = [it.text || ''].concat((it.items || []).map(x => (x.title || '') + ' ' + (x.text || ''))).join(' ').slice(0, 4000);
  }
}
if (!state.results.length) state.error = 'no organic results';
return [{ json: state }];

// One item per result URL, so each page is read by its own DataForSEO call.
const s = $input.first().json;
return s.results.filter(r => r.url).map(r => ({ json: { result_id: r.result_id, url: r.url } }));

// Words, characters, a 400-char digest and a content-form inventory from each page's markdown.
// Pages under 150 words are marked thin (JavaScript shell or bot wall) and left out of length statistics.
const state = JSON.parse(JSON.stringify($('Read pages?').first().json));
const asked = $('Split pages').all().map(i => i.json.result_id);
function analyse(md) {
  const WORD = /[\p{L}\p{N}]+/gu;
  const el = { tables: 0, ordered_lists: 0, unordered_lists: 0, images: 0, videos: 0 };
  const headings = [], paragraphs = [];
  let prev = '';
  for (const raw of md.split('\n')) {
    const line = raw.trim();
    const kind = line.startsWith('|') ? 'tables' : /^\d+[.)]\s/.test(line) ? 'ordered_lists' : /^[-*+]\s/.test(line) ? 'unordered_lists' : '';
    if (kind && kind !== prev) el[kind]++;
    prev = kind;
    el.images += (line.match(/!\[[^\]]*\]\(/g) || []).length;
    el.videos += (line.match(/youtube\.com\/(watch|embed)|youtu\.be\/|vimeo\.com\//g) || []).length;
    if (line.startsWith('#')) headings.push(line.replace(/^#+\s*/, ''));
    else if (!kind && !line.startsWith('>') && (line.match(WORD) || []).length >= 8) paragraphs.push(line);
  }
  const text = md.replace(/!?\[([^\]]*)\]\([^)]*\)/g, '$1');
  const parts = [];
  if (headings.length) parts.push('headings: ' + headings.slice(0, 8).join('; '));
  if (paragraphs.length) parts.push('text: ' + paragraphs.slice(0, 3).join(' '));
  return { words: (text.match(WORD) || []).length, chars: text.replace(/\s+/g, ' ').trim().length, digest: parts.join(' | ').slice(0, 400), elements: el };
}
$input.all().forEach((reply, i) => {
  const task = (reply.json.tasks || [])[0] || {};
  state.cost.pages += Number(task.cost || 0);
  const r = state.results.find(x => x.result_id === asked[i]);
  if (!r) return;
  const item = (((task.result || [])[0] || {}).items || [])[0] || {};
  const md = item.page_as_markdown || '';
  if (task.status_code !== 20000 || !md) { r.fetch_status = 'error'; return; }
  Object.assign(r, analyse(md));
  r.fetch_status = r.words >= 150 ? 'ok' : 'thin';
  if (r.fetch_status !== 'ok') r.digest = '';
});
return [{ json: state }];

// Search volume and seasonality. Seasonality is arithmetic: calendar-month means over the last 3 years; index = best month / worst month.
const state = JSON.parse(JSON.stringify($('Search volume?').first().json));
const task = ($input.first().json.tasks || [])[0] || {};
state.cost.volume += Number(task.cost || 0);
function seasonality(monthly) {
  const known = monthly.filter(m => m.volume != null);
  if (known.length < 12) return null;
  const byMonth = {};
  for (const m of known.slice(-36)) (byMonth[m.month] = byMonth[m.month] || []).push(m.volume);
  const means = Object.entries(byMonth).map(([k, v]) => [Number(k), v.reduce((a, b) => a + b, 0) / v.length]);
  const overall = means.reduce((a, m) => a + m[1], 0) / means.length;
  const profile = means.map(m => [m[0], overall ? m[1] / overall : 0]);
  const peak = profile.reduce((a, b) => (b[1] > a[1] ? b : a));
  const low = profile.reduce((a, b) => (b[1] < a[1] ? b : a));
  const sum = arr => arr.reduce((a, m) => a + m.volume, 0);
  const prev = known.length >= 24 ? sum(known.slice(-24, -12)) : 0;
  return { peak_month: peak[0], low_month: low[0], index: low[1] ? Math.round(100 * peak[1] / low[1]) / 100 : null, yoy: prev ? Math.round(1000 * (sum(known.slice(-12)) / prev - 1)) / 1000 : null };
}
const item = ((((task.result || [])[0]) || {}).items || [])[0];
if (item) {
  const info = item.keyword_info || {};
  const monthly = (info.monthly_searches || []).filter(m => m.year && m.month).map(m => ({ year: m.year, month: m.month, volume: m.search_volume })).sort((a, b) => a.year - b.year || a.month - b.month);
  state.demand = { volume: info.search_volume ?? null, cpc: info.cpc ?? null, difficulty: (item.keyword_properties || {}).keyword_difficulty ?? null, season: seasonality(monthly) };
}
return [{ json: state }];

// Estimated traffic per URL. A page with no known keywords is unknown (null), never zero.
const state = JSON.parse(JSON.stringify($('Traffic?').first().json));
const task = ($input.first().json.tasks || [])[0] || {};
state.cost.traffic += Number(task.cost || 0);
const etv = {};
for (const it of (((task.result || [])[0] || {}).items || [])) {
  const o = (it.metrics || {}).organic || {};
  etv[String(it.target).toLowerCase()] = o.count ? Number(o.etv || 0) : null; // DataForSEO lowercases targets
}
for (const r of state.results) r.etv = etv[r.url.toLowerCase()] ?? null;
return [{ json: state }];

// The model sees titles, snippets, highlighted phrases and page digests - never word counts, traffic or other numbers.
const state = $input.first().json;
const cfg = $('Config').first().json;
const payload = {
  source: 'serp', keyword: state.keyword, language: state.language_code, brief: '', serp_features: state.features,
  results: state.results.map(r => ({ result_id: r.result_id, rank: r.rank, url: r.url, domain: r.domain, title: r.title, description: r.description, highlighted: r.highlighted, digest: r.fetch_status === 'ok' ? r.digest : '' }))
};
const body = {
  model: cfg.model, max_tokens: 12000, reasoning: { enabled: false }, usage: { include: true }, response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: cfg.system_prompt },
    { role: 'user', content: 'Read these results and return the JSON object defined by your instructions.\n\n' + JSON.stringify(payload) }
  ]
};
return [{ json: { state, user: body.messages[1].content } }];

// The model grouped; this node counts. Coverage is unsplit, share splits a result that serves k intents 1/k to each,
// traffic share uses only known traffic. No reference length without at least 3 measured pages and a spread under 50x.
const s = JSON.parse(JSON.stringify($('Build prompt').first().json.state));
const resp = $input.first().json;
// The Basic LLM Chain reports neither cost nor tokens: unknown, not zero (check them in your OpenRouter activity).
s.cost.model = null;
s.tokens = { in: null, out: null };
const FENCE = String.fromCharCode(96).repeat(3);
let labels;
try {
  let raw = String(resp.text || '').trim();
  if (raw.startsWith(FENCE)) raw = raw.replace(/^[^\n]*\n/, '').split(FENCE)[0];
  // With response format json_object the chain already returns the parsed object.
  labels = Array.isArray(resp.intents) ? resp : JSON.parse(raw);
  if (!Array.isArray(labels.intents) || !labels.intents.length) throw new Error('no intents in the answer');
} catch (e) {
  s.error = 'model: ' + (typeof resp.error === 'string' ? resp.error : (resp.error && resp.error.message) || e.message);
  return [{ json: s }];
}
const ids = s.results.map(r => r.result_id);
const known = new Set(ids);
const placed = new Set();
for (const it of labels.intents) {
  it.result_ids = [...new Set((it.result_ids || []).map(String))].filter(id => known.has(id));
  it.result_ids.forEach(id => placed.add(id));
}
labels.intents = labels.intents.filter(it => it.result_ids.length);
const missing = ids.filter(id => !placed.has(id));
if (missing.length) labels.intents.push({ title: 'Unassigned results', searcher_goal: 'the model did not place these results', form: '', result_ids: missing, fallback: true });
const byId = Object.fromEntries(s.results.map(r => [r.result_id, r]));
const k = {};
labels.intents.forEach(it => it.result_ids.forEach(id => (k[id] = (k[id] || 0) + 1)));
const trafficTotal = s.results.filter(r => r.etv != null).reduce((a, r) => a + r.etv, 0);
const n = s.results.length;
const nearest = (arr, p) => (arr.length ? arr[Math.max(0, Math.min(arr.length - 1, Math.ceil(p / 100 * arr.length) - 1))] : null);
const rows = labels.intents.map(it => {
  const pages = it.result_ids.map(id => byId[id]);
  const words = pages.filter(p => p.fetch_status === 'ok').map(p => p.words).sort((a, b) => a - b);
  return {
    title: it.title || '', intent_type: it.intent_type || '', searcher_goal: it.searcher_goal || '', form: it.form || '', evidence: it.evidence || '', fallback: !!it.fallback,
    coverage: it.result_ids.length / n, share: it.result_ids.reduce((a, id) => a + 1 / k[id], 0) / n,
    traffic: trafficTotal ? it.result_ids.reduce((a, id) => a + (byId[id].etv || 0) / k[id], 0) / trafficTotal : null,
    ranks: pages.map(p => p.rank).sort((a, b) => a - b), words, median_words: nearest(words, 50), result_ids: it.result_ids
  };
});
const real = rows.filter(r => !r.fallback);
const top = real.slice().sort((a, b) => b.share - a.share || (b.traffic || 0) - (a.traffic || 0))[0];
const w = top ? top.words : [];
let basis = 'median_of_dominant_intent_pages';
if (w.length < 3) basis = 'insufficient_sample';
else if (w[w.length - 1] / w[0] > 50) basis = 'spread_too_wide';
const reliable = basis === 'median_of_dominant_intent_pages';
const warnings = [];
if (top && top.share < 0.4 && top.coverage < 0.5) warnings.push('mixed_serp');
if (real.filter(r => r.share >= 0.15).length >= 3) warnings.push('consider_separate_pages');
const byTraffic = real.filter(r => r.traffic != null).sort((a, b) => b.traffic - a.traffic)[0];
if (byTraffic && top && byTraffic !== top) warnings.push('traffic_disagrees');
if (labels.article_fits && labels.article_fits.value === false) warnings.push('serp_does_not_want_an_article');
if (missing.length) warnings.push('unassigned_results');
s.labels = labels;
s.rows = rows;
s.decision = {
  dominant: top ? top.title : '', form: top ? top.form : '', share: top ? top.share : null,
  length: reliable ? nearest(w, 50) : null, basis, genre: reliable ? (labels.expected_genre || '') : '',
  article_fits: labels.article_fits ? labels.article_fits.value : null, warnings
};
return [{ json: s }];

// One row for Summary, one per intent for Intents, one per result for Results, and the status update for the Keywords row.
const s = $input.first().json;
const cfg = $('Config').first().json;
const date = new Date().toISOString().slice(0, 10);
const r4 = v => (v == null ? '' : Math.round(v * 10000) / 10000);
const d = s.decision || {};
const dem = s.demand || {};
const season = dem.season || {};
const cost = s.cost;
const dfs = cost.serp + cost.pages + cost.volume + cost.traffic;
const summary = [[
  date, s.keyword, s.country_code, s.language_code, cfg.model, s.results.length, s.results.filter(r => r.fetch_status === 'ok').length,
  d.dominant || '', d.form || '', r4(d.share), d.genre || '', d.article_fits == null ? '' : String(d.article_fits), d.length ?? '', d.basis || '',
  dem.volume ?? '', dem.cpc ?? '', season.index ?? '', season.peak_month ?? '',
  s.error ? 'error: ' + s.error : (d.warnings || []).join(', '), (s.labels && s.labels.summary) || '',
  r4(dfs), r4(cost.model), s.tokens.in, s.tokens.out
]];
const intents = (s.rows || []).map(r => [date, s.keyword, r.title, r.intent_type, r.searcher_goal, r.form, r4(r.coverage), r4(r.share), r4(r.traffic), r.ranks.join(', '), r.median_words ?? '', r.evidence]);
if (!intents.length) intents.push([date, s.keyword, '(no intents: ' + (s.error || 'unknown') + ')']);
const intentOf = id => (s.rows || []).filter(r => r.result_ids.includes(id)).map(r => r.title).join('; ');
const results = s.results.map(r => [date, s.keyword, r.rank, r.url, r.title, r.domain, intentOf(r.result_id), r.words ?? '', r.fetch_status, r.etv ?? '']
  .concat(r.elements ? [r.elements.tables, r.elements.ordered_lists + r.elements.unordered_lists, r.elements.images, r.elements.videos] : ['', '', '', '']));
if (!results.length) results.push([date, s.keyword, '', '(no results: ' + (s.error || 'unknown') + ')']);
// Google Sheets nodes map fields by column name, so every row becomes an object keyed by the tab's header.
const HEAD = {
  summary: ['date','keyword','country_code','language_code','model','results','pages_read','dominant_intent','dominant_form','dominant_share','expected_genre','article_fits','reference_length_words','length_basis','search_volume','cpc','seasonality_index','peak_month','warnings','summary','cost_dataforseo_usd','cost_openrouter_usd','tokens_in','tokens_out'],
  intents: ['date','keyword','intent','intent_type','searcher_goal','form','coverage','share','traffic_share','ranks','median_words','evidence'],
  results: ['date','keyword','rank','url','title','domain','intents','words','fetch_status','traffic_etv','tables','lists','images','videos']
};
const obj = (head, row) => Object.fromEntries(head.map((h, i) => [h, row[i] ?? '']));
return [{ json: {
  summary: obj(HEAD.summary, summary[0]), intents: intents.map(r => obj(HEAD.intents, r)), results: results.map(r => obj(HEAD.results, r)),
  keyword_row: { row_number: s.row_number, status: s.error ? 'error' : 'done', processed_at: new Date().toISOString(), cost_usd: r4(dfs + cost.model) }
} }];
